// Cartografía vectorial de Leonida (lienzo 0-1000 x 0-700, origen arriba a la izquierda, Y hacia abajo).
// La geometría (costas, islas, batimetría, lagos y ríos, núcleos urbanos, arenales, marismas, relieve y red
// vial) se vectorizó a partir de los materiales de referencia locales de `public/ref Leonida map/` (carpeta
// fuera de git y fuera del build) y se incrusta aquí como datos de paths: sin imágenes, sin dependencias y
// sin red en tiempo de ejecución. Las referencias solo se usan como calca en el Modo Editor.
//
// Los marcadores reales de MongoDB se recalibraron sobre esta cartografía (ver `MARKER_SPOTS`).

export const MAP_W = 1000;
export const MAP_H = 700;

type P = [number, number];

/** PRNG determinista (mulberry32): la marisma y los textos son idénticos en cada carga. */
function prng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const r1 = (v: number): number => Math.round(v * 10) / 10;

/** Catmull-Rom -> Bézier cúbico (tensión 0.5). */
function smooth(pts: P[], closed: boolean): string {
  const n = pts.length;
  const at = (i: number): P => (closed ? pts[((i % n) + n) % n]! : pts[Math.min(n - 1, Math.max(0, i))]!);
  let d = `M${r1(pts[0]![0])} ${r1(pts[0]![1])}`;
  const last = closed ? n : n - 1;
  for (let i = 0; i < last; i++) {
    const p0 = at(i - 1);
    const p1 = at(i);
    const p2 = at(i + 1);
    const p3 = at(i + 2);
    d += `C${r1(p1[0] + (p2[0] - p0[0]) / 6)} ${r1(p1[1] + (p2[1] - p0[1]) / 6)} ${r1(p2[0] - (p3[0] - p1[0]) / 6)} ${r1(p2[1] - (p3[1] - p1[1]) / 6)} ${r1(p2[0])} ${r1(p2[1])}`;
  }
  return closed ? `${d}Z` : d;
}

/** Contorno irregular alrededor de una elipse (halos de región). */
function blob(cx: number, cy: number, rx: number, ry: number, seed: number, n = 14, noise = 0.12): string {
  const rnd = prng(seed);
  const pts: P[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const k = 1 + (rnd() - 0.5) * 2 * noise;
    pts.push([cx + Math.cos(a) * rx * k, cy + Math.sin(a) * ry * k]);
  }
  return smooth(pts, true);
}

