/** Marisma de Grassrivers: trazos cortos de vegetación acuática sobre el delta. */
export const SWAMP_D = (() => {
  const rnd = prng(55);
  let d = '';
  for (let i = 0; i < 70; i++) {
    const a = rnd() * Math.PI * 2;
    const rr = Math.sqrt(rnd());
    const x = 499.3 + Math.cos(a) * 90 * rr;
    const y = 541.3 + 14 + Math.sin(a) * 40 * rr;
    d += `M${r1(x - 2)} ${r1(y)}h4M${r1(x - 1)} ${r1(y + 1.6)}h2`;
  }
  return d;
})();

/** Cuadrícula de referencia cada 100 unidades. */
export const GRID_D = (() => {
  let d = '';
  for (let x = 0; x <= MAP_W; x += 100) d += `M${x} 0V${MAP_H}`;
  for (let y = 0; y <= MAP_H; y += 100) d += `M0 ${y}H${MAP_W}`;
  return d;
})();

